package ai.finsight.goal;
import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/goals")
public class FinancialGoalController {private final FinancialGoalService service;public FinancialGoalController(FinancialGoalService s){service=s;}@GetMapping public List<FinancialGoalService.View> list(Authentication a){return service.list(a.getName());}@PostMapping @ResponseStatus(HttpStatus.CREATED) public FinancialGoalService.View create(@Valid @RequestBody FinancialGoalService.Input i,Authentication a){return service.create(a.getName(),i);}@PutMapping("/{id}") public FinancialGoalService.View update(@PathVariable UUID id,@Valid @RequestBody FinancialGoalService.Input i,Authentication a){return service.update(a.getName(),id,i);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id,Authentication a){service.delete(a.getName(),id);}}
